// Transforms modern syntax
// Arrow functions → function expressions
// Async/await → Promise chains
// Classes → constructor functions
// Spread operator → Object.assign/Array.from
// Template literals → string concatenation

const TerserPlugin = require('terser-webpack-plugin');

module.exports = {
  optimization: {
    minimize: true,
    minimizer: [
      new TerserPlugin({
        terserOptions: {
          compress: {
            drop_console: true, // Remove console.log
            drop_debugger: true, // Remove debugger statements
            pure_funcs: ['console.log'], // Remove specific functions
            passes: 2 // Multiple passes for better optimization
          },
          mangle: {
            safari10: true // Support Safari 10
          },
          output: {
            comments: false, // Remove comments
            ascii_only: true // ASCII characters only
          }
        }
      })
    ]
  }
};

const MiniCssExtractPlugin = require('mini-css-extract-plugin');
const CssMinimizerPlugin = require('css-minimizer-webpack-plugin');
const PurgeCSSPlugin = require('purgecss-webpack-plugin');

module.exports = {
  plugins: [
    // Extract CSS to separate file
    new MiniCssExtractPlugin({
      filename: '[name].[contenthash].css'
    }),

    // Remove unused CSS
    new PurgeCSSPlugin({
      paths: glob.sync(['src/**/*.html', 'src/**/*.js']),
      defaultExtractor: content => content.match(/[\w-/:\.%]*/g) || []
    }),

    // Minify CSS
    new CssMinimizerPlugin()
  ],

  optimization: {
    minimizer: [
      `...`,
      new CssMinimizerPlugin()
    ]
  }
};

const ImageMinimizerPlugin = require('image-minimizer-webpack-plugin');

module.exports = {
  module: {
    rules: [
      {
        test: /\.(png|jpg|jpeg|gif|svg)$/i,
        type: 'asset/resource',
        generator: {
          filename: 'images/[name].[hash][ext]'
        },
        use: [
          {
            loader: ImageMinimizerPlugin.loader,
            options: {
              minimizerOptions: {
                plugins: [
                  ['imagemin-optipng'],
                  ['imagemin-pngquant'],
                  ['imagemin-svgo']
                ]
              }
            }
          }
        ]
      }
    ]
  }
};

const { build } = require('esbuild');

// Fast TypeScript transpilation
build({
  entryPoints: ['src/index.ts'],
  bundle: true,
  outfile: 'dist/bundle.js',
  minify: true,
  target: 'es2015',
  sourcemap: true
}).catch(() => process.exit(1));

